contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address newLog, uint minSumVal) public payable {
        // Decide initialization state via a first SetLogFile attempt, then check
        // whether the second call to SetLogFile (after possibly initializing) reverts.
        bool firstReverted;
        c.SetLogFile(newLog); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        // If the first call succeeded, the contract should not have been initialized;
        // now initialize it and ensure a second SetLogFile reverts.
        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initReverted = true; } else { initReverted = false; }

        bool secondReverted;
        c.SetLogFile(newLog); bool __rev2 = __ESBMC_reverted(); if (__rev2) { secondReverted = true; } else { secondReverted = false; }

        // General rule: the second SetLogFile (after initialization) must revert,
        // and the first SetLogFile only succeeds when the contract was uninitialized.
        assert(secondReverted && (firstReverted ? !initReverted : true));
    }

    receive() external payable {}
}

